/* M7 host: boot after wire_voices, config messages by type. See include/m7/pk7_host.h. */
#include <stdint.h>
#include "pk7_host.h"

#define PK7_HOST_MAGIC  0x37534f48u     /* 'HOS7' */

typedef struct {
    uint32_t type;
    void (*fn)(const uint8_t *buf, uint32_t len);
} pk7_msg_t;

/* generated by m7host.py (gen/pk7_host_gen.c) */
extern const pk7_msg_t pk7_msgs[];
extern const int pk7_n_msgs;
void pk7_run_inits(void);

extern uint32_t __pk_bss_start[], __pk_bss_end[];
uint32_t pk7_host_magic;                /* PK7_HOST_MAGIC once booted; the hook guards read it */

int pk7_host_booted(void)
{
    return pk7_host_magic == PK7_HOST_MAGIC;
}

/* replaces main's call to wire_voices; main inits the voices right after */
void pk7_boot(void)
{
    fw_wire_voices();
    for (uint32_t *p = __pk_bss_start; p < __pk_bss_end; p++)
        *p = 0;
    pk7_host_magic = PK7_HOST_MAGIC;
    pk7_run_inits();
}

/* replaces main's receive-and-drop of config messages it doesn't know */
int pk7_cfg_recv(int stream, uint32_t *hdr, uint8_t *buf)
{
    int got = fw_ipc_recv(stream, hdr, buf);
    if (got && pk7_host_booted())
        for (int i = 0; i < pk7_n_msgs; i++)
            if ((hdr[0] & 0xffu) == pk7_msgs[i].type)
                pk7_msgs[i].fn(buf, hdr[1]);
    return got;
}
